INSERT INTO categories (name, name_fr, slug, description, description_fr, display_order, active, created_by, updated_by) VALUES
    ('Burgers', 'Burgers', 'burgers', 'Smashed to order on a screaming-hot plancha, stacked on toasted brioche.', 'Smashés à la commande sur une plancha brûlante, montés sur brioche toastée.', 1, TRUE, 'seed', 'seed'),
    ('Sandwiches', 'Sandwichs', 'sandwiches', 'Bread from the bakery down the street, fillings cooked here, pressed or piled high.', 'Le pain de la boulangerie d''à côté, des garnitures cuisinées ici, pressées ou généreusement empilées.', 2, TRUE, 'seed', 'seed'),
    ('Plates', 'Assiettes', 'plates', 'From the grill and the oven: proper plates for a proper appetite.', 'Du grill et du four : de vraies assiettes pour un vrai appétit.', 3, TRUE, 'seed', 'seed'),
    ('Starters', 'Entrées', 'starters', 'To share, or not. Fries cut by hand every morning.', 'À partager, ou pas. Frites coupées à la main chaque matin.', 4, TRUE, 'seed', 'seed'),
    ('Salads', 'Salades', 'salads', 'Crunchy, bright and generous: never an afterthought.', 'Croquantes, vives et généreuses : jamais une option par défaut.', 5, TRUE, 'seed', 'seed'),
    ('Desserts', 'Desserts', 'desserts', 'Baked in-house, served warm when they should be.', 'Faits maison, servis tièdes quand il le faut.', 6, TRUE, 'seed', 'seed'),
    ('Drinks', 'Boissons', 'drinks', 'Lemonades squeezed to order, shakes, cold brew and tea.', 'Citronnades pressées minute, milkshakes, cold brew et thés glacés.', 7, TRUE, 'seed', 'seed'),
    ('Chef''s Specials', 'Suggestions du chef', 'specials', 'Limited runs from the kitchen. When they''re gone, they''re gone.', 'Des séries limitées de la cuisine. Quand il n''y en a plus, il n''y en a plus.', 8, TRUE, 'seed', 'seed');

INSERT INTO menu_items (category_id, name, name_fr, slug, description, description_fr, ingredients, ingredients_fr, price,
                        main_image_url, main_image_alt, available, featured, vegetarian, spicy, created_at, updated_at, created_by, updated_by)
SELECT c.id, v.name, v.name_fr, v.slug, v.description, v.description_fr, v.ingredients, v.ingredients_fr, v.price,
       v.main_image_url, v.main_image_alt, v.available, v.featured, v.vegetarian, v.spicy,
       now() - (v.age_days || ' days')::interval, now() - (v.age_days || ' days')::interval, 'seed', 'seed'
FROM (VALUES
    ('burgers', 'The Tasty Smash', 'Le Tasty Smash', 'the-tasty-smash', 'Our signature: two dry-aged beef patties smashed thin for a lacy crust, aged cheddar melted between them, house pickles and shallot jam on a toasted brioche bun.', 'Notre signature : deux steaks de bœuf maturé smashés finement pour une croûte dentelée, cheddar affiné fondu entre les deux, pickles maison et confit d''échalote sur brioche toastée.', 'Dry-aged beef, Aged cheddar, House pickles, Shallot jam, Tasty sauce, Brioche bun', 'Bœuf maturé, Cheddar affiné, Pickles maison, Confit d''échalote, Sauce Tasty, Pain brioche', 14.50, 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=1600&q=80', 'The Tasty Smash', TRUE, TRUE, FALSE, FALSE, 80),
    ('burgers', 'Smoked Brisket Burger', 'Burger au brisket fumé', 'smoked-brisket-burger', 'A beef patty topped with brisket smoked for twelve hours over oak, smoked gouda, crispy onions and a bourbon barbecue glaze.', 'Un steak de bœuf surmonté de brisket fumé douze heures au chêne, gouda fumé, oignons croustillants et laquage barbecue au bourbon.', 'Beef patty, 12-hour brisket, Smoked gouda, Crispy onions, Bourbon BBQ glaze, Brioche bun', 'Steak de bœuf, Brisket fumé 12 h, Gouda fumé, Oignons croustillants, Laque barbecue au bourbon, Pain brioche', 17.00, 'https://images.unsplash.com/photo-1594212699903-ec8a3eca50f5?auto=format&fit=crop&w=1600&q=80', 'Smoked Brisket Burger', TRUE, TRUE, FALSE, FALSE, 78),
    ('burgers', 'Truffle Mushroom Burger', 'Burger champignons et truffe', 'truffle-mushroom-burger', 'Charred beef patty, wild mushrooms roasted with thyme, melted Gruyère, peppery rocket and black truffle aioli in a charcoal bun.', 'Steak de bœuf saisi, champignons des bois rôtis au thym, Gruyère fondu, roquette poivrée et aïoli à la truffe noire dans un pain au charbon.', 'Beef patty, Wild mushrooms, Gruyère, Rocket, Truffle aioli, Charcoal bun', 'Steak de bœuf, Champignons des bois, Gruyère, Roquette, Aïoli à la truffe, Pain au charbon', 16.50, 'https://images.unsplash.com/photo-1582196016295-f8c8bd4b3a99?auto=format&fit=crop&w=1600&q=80', 'Truffle Mushroom Burger', TRUE, FALSE, FALSE, FALSE, 76),
    ('burgers', 'Nashville Hot Chicken', 'Poulet Nashville épicé', 'nashville-hot-chicken', 'Buttermilk-brined chicken thigh fried until it shatters, brushed with hot honey, finished with cool slaw and pickles.', 'Haut de cuisse mariné au babeurre, frit jusqu''à être bien croustillant, badigeonné de miel pimenté, avec coleslaw frais et pickles.', 'Buttermilk fried chicken, Hot honey, Slaw, Pickles, Potato bun', 'Poulet frit au babeurre, Miel pimenté, Coleslaw, Pickles, Pain de pomme de terre', 14.00, 'https://images.unsplash.com/photo-1606755962773-d324e0a13086?auto=format&fit=crop&w=1600&q=80', 'Nashville Hot Chicken', TRUE, FALSE, FALSE, TRUE, 74),
    ('burgers', 'Garden Stack', 'Garden Stack', 'garden-stack', 'A chickpea and roasted beetroot patty with grilled halloumi, harissa yoghurt, pickled red onion and crisp leaves.', 'Galette de pois chiches et betterave rôtie, halloumi grillé, yaourt à la harissa, oignon rouge mariné et jeunes pousses.', 'Chickpea & beetroot patty, Grilled halloumi, Harissa yoghurt, Pickled red onion, Seeded bun', 'Galette pois chiches et betterave, Halloumi grillé, Yaourt à la harissa, Oignon rouge mariné, Pain aux graines', 13.50, 'https://images.unsplash.com/photo-1481070555726-e2fe8357725c?auto=format&fit=crop&w=1600&q=80', 'Garden Stack', TRUE, FALSE, TRUE, FALSE, 72),
    ('burgers', 'Blue Cheese & Fig', 'Bleu et figue', 'blue-cheese-fig-burger', 'Beef patty, creamy blue cheese, slow-cooked fig compote, caramelised onions and watercress. Sweet, salty, unforgettable.', 'Steak de bœuf, bleu crémeux, compotée de figues mijotée, oignons caramélisés et cresson. Sucré, salé, inoubliable.', 'Beef patty, Blue cheese, Fig compote, Caramelised onions, Watercress, Brioche bun', 'Steak de bœuf, Bleu, Compotée de figues, Oignons caramélisés, Cresson, Pain brioche', 16.00, 'https://images.unsplash.com/photo-1553979459-d2229ba7433b?auto=format&fit=crop&w=1600&q=80', 'Blue Cheese & Fig', FALSE, FALSE, FALSE, FALSE, 70),
    ('sandwiches', 'Grilled Chicken Club', 'Club au poulet grillé', 'grilled-chicken-club', 'Triple-decker of grilled free-range chicken, smoked beef bacon, tomato, lettuce and lemon mayo on toasted sourdough.', 'Triple étage de poulet fermier grillé, bacon de bœuf fumé, tomate, laitue et mayonnaise citronnée sur pain au levain toasté.', 'Free-range chicken, Smoked beef bacon, Tomato, Lettuce, Lemon mayo, Sourdough', 'Poulet fermier, Bacon de bœuf fumé, Tomate, Laitue, Mayonnaise citronnée, Pain au levain', 13.50, 'https://images.unsplash.com/photo-1539252554453-80ab65ce3586?auto=format&fit=crop&w=1600&q=80', 'Grilled Chicken Club', TRUE, FALSE, FALSE, FALSE, 68),
    ('sandwiches', 'Steak & Chimichurri Ciabatta', 'Ciabatta steak et chimichurri', 'steak-chimichurri-ciabatta', 'Flank steak grilled pink and sliced thin, bright chimichurri, roasted peppers and provolone in a crusty ciabatta.', 'Bavette grillée rosée et tranchée finement, chimichurri vif, poivrons rôtis et provolone dans une ciabatta croustillante.', 'Flank steak, Chimichurri, Roasted peppers, Provolone, Ciabatta', 'Bavette, Chimichurri, Poivrons rôtis, Provolone, Ciabatta', 16.50, 'https://images.unsplash.com/photo-1554433607-66b5efe9d304?auto=format&fit=crop&w=1600&q=80', 'Steak & Chimichurri Ciabatta', TRUE, TRUE, FALSE, FALSE, 66),
    ('sandwiches', 'Sourdough Tuna Melt', 'Tuna melt au levain', 'tuna-melt', 'Line-caught tuna with capers and dill, sharp cheddar, griddled in butter until golden on both sides.', 'Thon de ligne aux câpres et à l''aneth, cheddar corsé, doré au beurre sur la plancha des deux côtés.', 'Line-caught tuna, Capers, Dill, Cheddar, Sourdough', 'Thon de ligne, Câpres, Aneth, Cheddar, Pain au levain', 12.50, 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=1600&q=80', 'Sourdough Tuna Melt', TRUE, FALSE, FALSE, FALSE, 64),
    ('sandwiches', 'Pastrami Reuben', 'Reuben au pastrami', 'pastrami-reuben', 'Beef pastrami cured and smoked in-house, piled high with sauerkraut, Swiss cheese and Russian dressing on grilled rye.', 'Pastrami de bœuf saumuré et fumé maison, généreusement empilé avec choucroute, emmental et sauce russe sur pain de seigle grillé.', 'House pastrami, Sauerkraut, Swiss cheese, Russian dressing, Rye bread', 'Pastrami maison, Choucroute, Emmental, Sauce russe, Pain de seigle', 15.00, 'https://images.unsplash.com/photo-1550507992-eb63ffee0847?auto=format&fit=crop&w=1600&q=80', 'Pastrami Reuben', TRUE, TRUE, FALSE, FALSE, 62),
    ('sandwiches', 'Caprese Focaccia', 'Focaccia caprese', 'caprese-focaccia', 'Buffalo mozzarella, heirloom tomatoes, basil pesto and aged balsamic in our rosemary focaccia, baked every morning.', 'Mozzarella di bufala, tomates anciennes, pesto de basilic et balsamique vieilli dans notre focaccia au romarin, cuite chaque matin.', 'Buffalo mozzarella, Heirloom tomatoes, Basil pesto, Aged balsamic, Rosemary focaccia', 'Mozzarella di bufala, Tomates anciennes, Pesto de basilic, Balsamique vieilli, Focaccia au romarin', 12.00, 'https://images.unsplash.com/photo-1592415486689-125cbbfcbee2?auto=format&fit=crop&w=1600&q=80', 'Caprese Focaccia', TRUE, FALSE, TRUE, FALSE, 60),
    ('sandwiches', 'Crispy Fish Sandwich', 'Sandwich au poisson croustillant', 'crispy-fish-sandwich', 'Beer-battered cod, tartare sauce with plenty of herbs, shredded lettuce and a squeeze of lemon on a soft potato bun.', 'Cabillaud en pâte à bière, sauce tartare bien herbacée, laitue émincée et un trait de citron sur pain de pomme de terre moelleux.', 'Beer-battered cod, Tartare sauce, Lettuce, Lemon, Potato bun', 'Cabillaud en pâte à bière, Sauce tartare, Laitue, Citron, Pain de pomme de terre', 13.50, 'https://images.unsplash.com/photo-1553909489-cd47e0907980?auto=format&fit=crop&w=1600&q=80', 'Crispy Fish Sandwich', TRUE, FALSE, FALSE, FALSE, 58),
    ('sandwiches', 'The Italian Hero', 'L''Italian Hero', 'italian-hero', 'Mortadella, spicy beef salami, provolone, marinated peppers, shaved onion and oregano vinaigrette in a seeded baguette.', 'Mortadelle, salami de bœuf piquant, provolone, poivrons marinés, oignon émincé et vinaigrette à l''origan dans une baguette aux graines.', 'Mortadella, Spicy beef salami, Provolone, Marinated peppers, Oregano vinaigrette, Seeded baguette', 'Mortadelle, Salami de bœuf piquant, Provolone, Poivrons marinés, Vinaigrette à l''origan, Baguette aux graines', 14.00, 'https://images.unsplash.com/photo-1485451456034-3f9391c6f769?auto=format&fit=crop&w=1600&q=80', 'The Italian Hero', TRUE, FALSE, FALSE, TRUE, 56),
    ('plates', 'Grilled Ribeye', 'Entrecôte grillée', 'grilled-ribeye', 'A 300 g ribeye charred over high heat and rested, served with peppercorn sauce, hand-cut fries and a dressed green salad.', 'Une entrecôte de 300 g saisie à feu vif puis reposée, servie avec sauce au poivre, frites maison et salade verte assaisonnée.', 'Ribeye 300 g, Peppercorn sauce, Hand-cut fries, Green salad', 'Entrecôte 300 g, Sauce au poivre, Frites maison, Salade verte', 29.00, 'https://images.unsplash.com/photo-1600891964092-4316c288032e?auto=format&fit=crop&w=1600&q=80', 'Grilled Ribeye', TRUE, TRUE, FALSE, FALSE, 54),
    ('plates', 'Half Roast Chicken', 'Demi-poulet rôti', 'half-roast-chicken', 'Herb-brined free-range chicken, roasted until the skin crackles, with lemon and garlic jus, roast potatoes and greens.', 'Poulet fermier saumuré aux herbes, rôti jusqu''à ce que la peau croustille, jus citron-ail, pommes rôties et légumes verts.', 'Free-range chicken, Lemon & garlic jus, Roast potatoes, Seasonal greens', 'Poulet fermier, Jus citron et ail, Pommes de terre rôties, Légumes de saison', 21.00, 'https://images.unsplash.com/photo-1532550907401-a500c9a57435?auto=format&fit=crop&w=1600&q=80', 'Half Roast Chicken', TRUE, FALSE, FALSE, FALSE, 52),
    ('plates', 'Crispy-Skin Salmon', 'Saumon à la peau croustillante', 'seared-salmon', 'Salmon seared skin-side down until glassy-crisp, beurre blanc with chives, crushed new potatoes and charred asparagus.', 'Saumon saisi côté peau jusqu''à être bien croustillant, beurre blanc à la ciboulette, pommes grenaille écrasées et asperges grillées.', 'Salmon fillet, Beurre blanc, Chives, New potatoes, Asparagus', 'Pavé de saumon, Beurre blanc, Ciboulette, Pommes grenaille, Asperges', 24.50, 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?auto=format&fit=crop&w=1600&q=80', 'Crispy-Skin Salmon', TRUE, FALSE, FALSE, FALSE, 50),
    ('plates', 'Lamb Kofta Skewers', 'Brochettes de kefta d''agneau', 'lamb-kofta', 'Spiced lamb kofta off the grill with tahini, parsley tabbouleh, charred tomato and warm flatbread.', 'Kefta d''agneau épicée grillée, tahini, taboulé au persil, tomate grillée et pain plat tiède.', 'Lamb kofta, Tahini, Tabbouleh, Charred tomato, Flatbread', 'Kefta d''agneau, Tahini, Taboulé, Tomate grillée, Pain plat', 19.50, 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1600&q=80', 'Lamb Kofta Skewers', TRUE, FALSE, FALSE, TRUE, 48),
    ('plates', 'Wild Mushroom Tagliatelle', 'Tagliatelles aux champignons', 'wild-mushroom-tagliatelle', 'Fresh egg tagliatelle tossed with sautéed wild mushrooms, garlic, cream, parmesan and a few drops of truffle oil.', 'Tagliatelles fraîches aux œufs, champignons des bois sautés, ail, crème, parmesan et quelques gouttes d''huile de truffe.', 'Egg tagliatelle, Wild mushrooms, Garlic, Parmesan, Truffle oil', 'Tagliatelles aux œufs, Champignons des bois, Ail, Parmesan, Huile de truffe', 18.00, 'https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&w=1600&q=80', 'Wild Mushroom Tagliatelle', TRUE, FALSE, TRUE, FALSE, 46),
    ('plates', 'Sticky Beef Short Ribs', 'Travers de bœuf laqués', 'sticky-short-ribs', 'Beef short ribs braised low and slow, then lacquered on the grill with our smoky glaze. Served with slaw and fries.', 'Travers de bœuf braisés longuement à basse température, puis laqués au grill avec notre sauce fumée. Servis avec coleslaw et frites.', 'Beef short ribs, Smoky glaze, Slaw, Hand-cut fries', 'Travers de bœuf, Laque fumée, Coleslaw, Frites maison', 26.00, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=1600&q=80', 'Sticky Beef Short Ribs', TRUE, FALSE, FALSE, FALSE, 44),
    ('plates', 'Garlic Shrimp Linguine', 'Linguine aux crevettes à l''ail', 'shrimp-linguine', 'Linguine with sautéed shrimp, garlic, chilli, cherry tomatoes and white wine, finished with parsley and lemon zest.', 'Linguine aux crevettes sautées, ail, piment, tomates cerises et vin blanc, relevées de persil et de zeste de citron.', 'Linguine, Shrimp, Garlic, Chilli, Cherry tomatoes, Lemon zest', 'Linguine, Crevettes, Ail, Piment, Tomates cerises, Zeste de citron', 21.50, 'https://images.unsplash.com/photo-1563379926898-05f4575a45d8?auto=format&fit=crop&w=1600&q=80', 'Garlic Shrimp Linguine', TRUE, FALSE, FALSE, FALSE, 42),
    ('starters', 'Loaded Tasty Fries', 'Frites Tasty garnies', 'loaded-tasty-fries', 'Hand-cut fries under warm cheddar sauce, crispy shallots, pickled jalapeños and a zigzag of Tasty sauce.', 'Frites maison nappées de sauce cheddar, échalotes croustillantes, jalapeños marinés et un trait de sauce Tasty.', 'Hand-cut fries, Cheddar sauce, Crispy shallots, Pickled jalapeños, Tasty sauce', 'Frites maison, Sauce cheddar, Échalotes croustillantes, Jalapeños marinés, Sauce Tasty', 8.50, 'https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=1600&q=80', 'Loaded Tasty Fries', TRUE, FALSE, TRUE, TRUE, 40),
    ('starters', 'Crispy Chicken Wings', 'Ailes de poulet croustillantes', 'crispy-chicken-wings', 'Eight wings, twice-fried and tossed in hot honey or garlic parmesan. Ask for extra napkins.', 'Huit ailes frites deux fois, enrobées de miel pimenté ou d''ail et parmesan. Pensez aux serviettes.', 'Chicken wings, Hot honey, Garlic parmesan, Ranch dip', 'Ailes de poulet, Miel pimenté, Ail et parmesan, Sauce ranch', 10.00, 'https://images.unsplash.com/photo-1608039755401-742074f0548d?auto=format&fit=crop&w=1600&q=80', 'Crispy Chicken Wings', TRUE, FALSE, FALSE, TRUE, 38),
    ('starters', 'Hand-Cut Fries', 'Frites maison', 'hand-cut-fries', 'Potatoes peeled and cut every morning, fried twice, salted with flaky sea salt. Served with Tasty sauce.', 'Pommes de terre épluchées et coupées chaque matin, frites deux fois, relevées de fleur de sel. Servies avec la sauce Tasty.', 'Potatoes, Sea salt, Tasty sauce', 'Pommes de terre, Fleur de sel, Sauce Tasty', 5.00, 'https://images.unsplash.com/photo-1585109649139-366815a0d713?auto=format&fit=crop&w=1600&q=80', 'Hand-Cut Fries', TRUE, FALSE, TRUE, FALSE, 36),
    ('starters', 'Brisket Tacos', 'Tacos au brisket', 'brisket-tacos', 'Three soft corn tacos filled with our smoked brisket, pickled red onion, coriander and chipotle crema.', 'Trois tacos de maïs moelleux garnis de notre brisket fumé, oignon rouge mariné, coriandre et crème au chipotle.', 'Smoked brisket, Corn tortillas, Pickled red onion, Coriander, Chipotle crema', 'Brisket fumé, Tortillas de maïs, Oignon rouge mariné, Coriandre, Crème au chipotle', 11.00, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=1600&q=80', 'Brisket Tacos', TRUE, FALSE, FALSE, TRUE, 34),
    ('salads', 'Grilled Chicken Caesar', 'César au poulet grillé', 'grilled-chicken-caesar', 'Crisp romaine, grilled chicken, shaved parmesan, sourdough croutons and a proper anchovy dressing.', 'Romaine croquante, poulet grillé, copeaux de parmesan, croûtons au levain et une vraie sauce aux anchois.', 'Romaine, Grilled chicken, Parmesan, Sourdough croutons, Anchovy dressing', 'Romaine, Poulet grillé, Parmesan, Croûtons au levain, Sauce aux anchois', 13.00, 'https://images.unsplash.com/photo-1512852939750-1305098529bf?auto=format&fit=crop&w=1600&q=80', 'Grilled Chicken Caesar', TRUE, FALSE, FALSE, FALSE, 32),
    ('salads', 'Quinoa & Roasted Veg Bowl', 'Bowl quinoa et légumes rôtis', 'quinoa-roasted-veg-bowl', 'Quinoa, roasted squash, chickpeas, avocado, crumbled feta and a lemon-tahini dressing.', 'Quinoa, courge rôtie, pois chiches, avocat, feta émiettée et sauce citron-tahini.', 'Quinoa, Roasted squash, Chickpeas, Avocado, Feta, Lemon-tahini', 'Quinoa, Courge rôtie, Pois chiches, Avocat, Feta, Citron-tahini', 12.50, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=1600&q=80', 'Quinoa & Roasted Veg Bowl', TRUE, FALSE, TRUE, FALSE, 30),
    ('salads', 'Steak & Blue Cheese Salad', 'Salade bavette et bleu', 'steak-blue-cheese-salad', 'Sliced flank steak over mixed leaves with blue cheese, candied walnuts, pear and a balsamic dressing.', 'Bavette tranchée sur mesclun, bleu, noix caramélisées, poire et vinaigrette balsamique.', 'Flank steak, Mixed leaves, Blue cheese, Candied walnuts, Pear, Balsamic', 'Bavette, Mesclun, Bleu, Noix caramélisées, Poire, Balsamique', 15.50, 'https://images.unsplash.com/photo-1540189549336-e6e99c3679fe?auto=format&fit=crop&w=1600&q=80', 'Steak & Blue Cheese Salad', TRUE, FALSE, FALSE, FALSE, 28),
    ('desserts', 'Salted Caramel Brownie', 'Brownie au caramel salé', 'salted-caramel-brownie', 'Dark chocolate brownie served warm with a ribbon of salted caramel and a scoop of vanilla ice cream.', 'Brownie au chocolat noir servi tiède avec un ruban de caramel salé et une boule de glace vanille.', 'Dark chocolate, Salted caramel, Vanilla ice cream', 'Chocolat noir, Caramel salé, Glace vanille', 7.50, 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=1600&q=80', 'Salted Caramel Brownie', TRUE, TRUE, TRUE, FALSE, 26),
    ('desserts', 'Burnt Basque Cheesecake', 'Cheesecake basque brûlé', 'basque-cheesecake', 'Deeply caramelised outside, barely set inside, with a blueberry compote on the side.', 'Bien caramélisé à l''extérieur, à peine pris à l''intérieur, servi avec une compotée de myrtilles.', 'Cream cheese, Burnt caramel top, Blueberry compote', 'Fromage frais, Dessus caramélisé, Compotée de myrtilles', 8.00, 'https://images.unsplash.com/photo-1567171466295-4afa63d45416?auto=format&fit=crop&w=1600&q=80', 'Burnt Basque Cheesecake', TRUE, FALSE, TRUE, FALSE, 24),
    ('desserts', 'Tiramisu', 'Tiramisu', 'tiramisu', 'Espresso-soaked savoiardi, whipped mascarpone and a thick dusting of cocoa. Made every afternoon.', 'Biscuits savoiardi imbibés d''espresso, mascarpone fouetté et une généreuse couche de cacao. Préparé chaque après-midi.', 'Mascarpone, Espresso, Savoiardi, Cocoa', 'Mascarpone, Espresso, Savoiardi, Cacao', 7.50, 'https://images.unsplash.com/photo-1571877227200-a0d98ea607e9?auto=format&fit=crop&w=1600&q=80', 'Tiramisu', TRUE, FALSE, TRUE, FALSE, 22),
    ('desserts', 'Chocolate Fudge Cake', 'Gâteau fondant au chocolat', 'chocolate-fudge-cake', 'Three layers of moist chocolate sponge and fudge frosting. One slice feeds two, in theory.', 'Trois étages de génoise moelleuse au chocolat et glaçage fondant. Une part pour deux, en théorie.', 'Chocolate sponge, Fudge frosting, Cocoa nibs', 'Génoise au chocolat, Glaçage fondant, Éclats de cacao', 8.50, 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=1600&q=80', 'Chocolate Fudge Cake', FALSE, FALSE, TRUE, FALSE, 20),
    ('drinks', 'Fresh Mint Lemonade', 'Citronnade à la menthe', 'fresh-mint-lemonade', 'Lemons squeezed to order with fresh mint and a touch of cane sugar. Still or sparkling.', 'Citrons pressés minute, menthe fraîche et une touche de sucre de canne. Plate ou pétillante.', 'Fresh lemon, Mint, Cane sugar', 'Citron frais, Menthe, Sucre de canne', 4.50, 'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?auto=format&fit=crop&w=1600&q=80', 'Fresh Mint Lemonade', TRUE, FALSE, TRUE, FALSE, 18),
