    announcement_fr = 'Le Double smash wagyu est de retour pour la saison.',
    promo_title = 'Chef''s special: Wagyu Double Smash',
    promo_title_fr = 'Suggestion du chef : Double smash wagyu',
    promo_text = 'Two wagyu-blend patties, brown-butter onions, aged Comté and black garlic mayo. Made in small batches each week, until the wagyu runs out.',
    promo_text_fr = 'Deux steaks de bœuf wagyu, oignons au beurre noisette, Comté affiné et mayonnaise à l''ail noir. En petites séries chaque semaine, jusqu''à épuisement.',
    promo_enabled = TRUE,
    promo_menu_item_id = (SELECT id FROM menu_items WHERE slug = 'wagyu-double-smash'),
    updated_by = 'seed'
WHERE id = 1;

-- Demo opening hours: closed Mondays, late on Friday and Saturday (closing after midnight).
UPDATE opening_hours SET closed = TRUE WHERE day_of_week = 1;
UPDATE opening_hours SET opens_at = '11:30', closes_at = '22:30', closed = FALSE WHERE day_of_week IN (2, 3, 4);
UPDATE opening_hours SET opens_at = '11:30', closes_at = '00:30', closed = FALSE WHERE day_of_week IN (5, 6);
UPDATE opening_hours SET opens_at = '12:00', closes_at = '21:30', closed = FALSE WHERE day_of_week = 7;
